INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:receptor_tanimi', 'medchem', 'reseptor-etkilesimleri', 1, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[2,3,5,6]::int[], 'Reseptör ve bağ gücü dengesi', 'İlaç etkisini anlamak için ilaç ile reseptör arasındaki bağ kuvvetlerini bilmek gerekir (Slayt 2). Bu bağlar reseptörün şeklini değiştirebilecek kadar güçlü olmalı; sinyal iletildikten sonra ilacı kolayca serbest bırakacak kadar da geri dönüşümlü olmalıdır (Slayt 2). Reseptör, hormon ve nöromediyatör gibi endojen maddelere ve ilaçlara seçici afinite gösteren, fizyolojik etkiyi başlatan hücresel biyomakromoleküldür (Slayt 3). Reseptörlerin çoğu hücre zarı yüzeyindedir; steroit ve tiroit hormon reseptörleri ise hücre içindedir (Slayt 5). İki işlevi vardır: ligandı seçici tanımak ve kimyasal sinyali biyolojik sinyale çevirmek (Slayt 6).',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"İlaç reseptöre bağlandı ve sinyal iletilecek. İlaç-reseptör bağları nasıl olmalıdır?","options":[{"id":"correct","text":"Reseptörün şeklini değiştirecek kadar güçlü, sinyalden sonra ilacı bırakacak kadar geri dönüşümlü","isCorrect":true},{"id":"STRONGEST_IS_BEST","text":"Mümkün olan en güçlü ve kalıcı bağlar; böylece etki en uzun sürer","isCorrect":false,"distractorRationale":"Kalıcı etki genellikle istenmez; yalnızca bazı ilaç gruplarında aranır (Slayt 9)."},{"id":"MISSING_SHAPE_CHANGE","text":"Çok zayıf bağlar; böylece ilaç reseptörden hep kolayca ayrılır","isCorrect":false,"distractorRationale":"Bağlar reseptörün şeklini değiştirebilecek kadar güçlü de olmalıdır (Slayt 2)."}],"isMultiSelect":false,"explanation":"Bağlar, reseptörün şeklini değiştirebilecek kadar güçlü, sinyal iletildikten sonra ilacı kolayca serbest bırakacak kadar geri dönüşümlü olmalıdır.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":2}}}'::jsonb, 'İlaç reseptöre bağlandı ve sinyal iletilecek. Sence ilaç-reseptör bağları nasıl olmalı? Önce tahmin et, sonra seçimini kontrol et.',
  '["Düşün: ilaç sinyali verdikten sonra reseptörde sonsuza kadar kalsaydı ne olurdu? Reseptör bir sonraki sinyale hazır olabilir miydi?","İki şartı birlikte ara: bağ reseptörün şeklini değiştirebilmeli, ama iş bitince ilaç serbest kalabilmeli. Hangi seçenek ikisini birden sağlıyor?","Bağlar reseptörün şeklini değiştirecek kadar güçlü, sinyalden sonra ilacı kolayca bırakacak kadar geri dönüşümlü olmalıdır. (Slayt 2)"]'::jsonb, '{"STRONGEST_IS_BEST":{"diagnosis":"En güçlü ve kalıcı bağ en iyisi sanılıyor. Slayta göre kalıcı, geri dönüşümsüz etki genellikle istenmez; yalnızca antibakteriyel, antiparaziter, antifungal ve antikanser gibi bazı etkilerde aranır.","slides":[2,9]},"MISSING_SHAPE_CHANGE":{"diagnosis":"Çok zayıf bağ yeterli sanılıyor. Slayt, bağların reseptörün şeklini değiştirebilecek kadar güçlü olmasını da şart koşar.","slides":[2]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
