INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:kovalan_baglar', 'medchem', 'reseptor-etkilesimleri', 2, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[9,10,11,12,13]::int[], 'Kovalan bağlar', 'Kovalan bağlar elektron çiftlerinin ortaklanmasıyla oluşur ve ilaç-reseptör arasındaki en kuvvetli bağlardır; ancak ilaçların çoğu geri dönüşümsüz kovalan bağ yapabilecek fonksiyonel gruplar taşımadığı için seyrek görülür (Slayt 9). Uzun süreli, geri dönüşümsüz etki yaptığı için genelde istenmez; bazı antibakteriyel, antiparaziter, antifungal ve antikanser etkilerde istenir (Slayt 9). Üç reaksiyon türü: alkilasyon, açilasyon, fosforilasyon (Slayt 9). Alkilleyici kanser ilaçları reseptör proteinlerin serbest amino gruplarını veya nükleik asitlerin adenil ya da fosfat gruplarını alkiler; çoğu seçici değildir (Slayt 10). Beta-laktam halkalı antibiyotikler, transpeptidaz enziminin serin hidroksilini açiller (Slayt 11). Organofosfatlar, aktif bölgesinde serin taşıyan enzimleri fosforiller (Slayt 12). Ağır metal (As, Bi, Sb vb.) taşıyan antiparaziter ilaçlar enzimin tiyol gruplarıyla kovalan bağ yapar (Slayt 13).',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"Organofosfat insektisitler asetilkolin esteraz enzimine hangi reaksiyonla bağlanır?","options":[{"id":"correct","text":"Aktif bölgedeki serini fosforiller; kovalan bağ oluşur","isCorrect":true},{"id":"CONFUSES_ACYLATION","text":"Enzimdeki serin hidroksilini açiller","isCorrect":false,"distractorRationale":"Açilasyon beta-laktam antibiyotiklerin mekanizmasıdır (Slayt 11); organofosfatlar fosforiller (Slayt 12)."},{"id":"CONFUSES_THIOL_TARGET","text":"Enzimin tiyol gruplarıyla kovalan bağ yapar","isCorrect":false,"distractorRationale":"Tiyol hedefi ağır metalli antiparaziter ilaçlara aittir (Slayt 13)."},{"id":"TREATS_COVALENT_AS_WEAK","text":"Zayıf ve geri dönüşümlü bir bağ kurar","isCorrect":false,"distractorRationale":"Kovalan bağlar en kuvvetli ve geri dönüşümsüz bağlardır (Slayt 9)."}],"isMultiSelect":false,"explanation":"Organofosfatlar, aktif bölgesinde serin taşıyan enzimleri fosforiller; örnek olarak asetilkolin esteraz ve butiril kolin esteraz verilir.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":12}}}'::jsonb, 'Organofosfat insektisitler asetilkolin esteraz enzimine nasıl bağlanır? Reaksiyon adını ve enzimdeki hedef grubu düşün.',
  '["Önce reaksiyon adını düşün: alkilasyon, açilasyon ve fosforilasyon. Organofosfat bileşiğinin adı hangisini düşündürüyor?","Slaytta serin hidroksili iki ilaç grubunun hedefi. Biri transpeptidaz enzimini, öbürü asetilkolin esteraz gibi enzimleri etkiliyor. Organofosfat hangisi?","Organofosfatlar, aktif bölgesinde serin taşıyan enzimleri fosforiller ve geri dönüşümsüz kovalan bağ oluşturur. (Slayt 12)"]'::jsonb, '{"CONFUSES_ACYLATION":{"diagnosis":"Açilasyon ile fosforilasyon karıştırılıyor. Serin hidroksilini açilleyenler beta-laktam antibiyotiklerdir; organofosfatlar fosforiller.","slides":[11,12]},"CONFUSES_THIOL_TARGET":{"diagnosis":"Hedef grup karıştırılıyor. Tiyol gruplarıyla bağ kuranlar ağır metalli antiparaziter ilaçlardır; organofosfatın hedefi enzimdeki serindir.","slides":[13,12]},"TREATS_COVALENT_AS_WEAK":{"diagnosis":"Kovalan bağ geri dönüşümlü sanılıyor. Slayta göre kovalan bağlar en kuvvetli ve geri dönüşümsüz etkileşimlerdir.","slides":[9,12]}}'::jsonb, 'draft', now())
