INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:iyonik_bag', 'medchem', 'reseptor-etkilesimleri', 3, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[13,14]::int[], 'İyonik bağ', 'İyonik bağ, zıt yüklü iyonlar arasındaki elektrostatik çekimle oluşur (Slayt 13). Gücü zıt yüklerin miktarına, yükler arasındaki mesafeye ve ortamın dielektrik sabitine bağlıdır (Slayt 13). Mesafe ve ortamın dielektrik sabiti arttıkça bağın gücü zayıflar (Slayt 13). Zayıf asit veya baz özellikli ilaçlar ve reseptörler fizyolojik pH''da iyonlaşabilen gruplar taşır; zıt yüklü iyonlar belli bir mesafeye yaklaşınca iyonik bağ oluşur (Slayt 14). Slaytlarda sayısal formül veya değer yoktur. [NOT IN MATERIALS]',
  'PredictThenReveal', '{"type":"PredictThenReveal","config":{"prompt":"Mesafe ve ortamın dielektrik sabiti artarsa iyonik bağın gücüne ne olur?","scenarioDescription":"Fizyolojik pH''da iyonlaşmış bir ilaç grubu ile reseptördeki zıt yüklü grup arasında iyonik bağ var. Gruplar birbirinden uzaklaşıyor ve çevrenin dielektrik sabiti artıyor.","options":[{"id":"correct","label":"Bağ zayıflar","isCorrect":true},{"id":"DISTANCE_NO_EFFECT","label":"Değişmez; zıt yükler her mesafede aynı çeker","isCorrect":false,"misconceptionFeedback":"Slayta göre mesafe arttıkça iyonik bağın gücü zayıflar (Slayt 13)."},{"id":"DISTANCE_STRENGTHENS","label":"Bağ güçlenir","isCorrect":false,"misconceptionFeedback":"Slayta göre mesafe ve dielektrik sabiti arttıkça bağ zayıflar (Slayt 13)."},{"id":"SOLVENT_IRRELEVANT","label":"Yalnızca mesafe etkiler; ortamın etkisi yoktur","isCorrect":false,"misconceptionFeedback":"Ortamın dielektrik sabiti de bağ gücünü etkiler (Slayt 13)."}],"revealedOutcome":"Mesafe ve ortamın dielektrik sabiti arttıkça iyonik bağın gücü zayıflar.","explanation":"İyonik bağın gücü yük miktarına, yükler arası mesafeye ve ortamın dielektrik sabitine bağlıdır.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":13}}}'::jsonb, 'Zıt yüklü iki grup birbirinden uzaklaşıyor ve ortamın dielektrik sabiti artıyor. Önce iyonik bağın gücüne ne olacağını tahmin et.',
  '["Zıt yüklere uzaktan baktığını düşün. Aradaki mesafe büyüdükçe çekim aynı mı kalır?","Bağ gücü üç şeye bağlı: yük miktarı, mesafe ve dielektrik sabiti. Bu soruda hangi ikisi artıyor, gücü hangi yöne iter?","Mesafe ve ortamın dielektrik sabiti arttıkça iyonik bağın gücü zayıflar. (Slayt 13)"]'::jsonb, '{"DISTANCE_NO_EFFECT":{"diagnosis":"Yükler zıtsa mesafe önemsiz sanılıyor. Slayta göre mesafe arttıkça bağ zayıflar.","slides":[13]},"DISTANCE_STRENGTHENS":{"diagnosis":"Uzaklaşınca bağın güçleneceği sanılıyor. Slayta göre mesafe ve dielektrik sabiti arttıkça bağ zayıflar.","slides":[13]},"SOLVENT_IRRELEVANT":{"diagnosis":"Ortamın etkisiz olduğu sanılıyor. Slayta göre ortamın dielektrik sabiti de bağ gücünü belirler.","slides":[13]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
  slide_numbers = EXCLUDED.slide_numbers, concept_title = EXCLUDED.concept_title,
  scientific_summary = EXCLUDED.scientific_summary, recommended_widget = EXCLUDED.recommended_widget,
  initial_widget_state = EXCLUDED.initial_widget_state, student_task = EXCLUDED.student_task,
