INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:hidrojen_bagi', 'medchem', 'reseptor-etkilesimleri', 4, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[15,16,17]::int[], 'Hidrojen bağı (donör ve akseptör)', 'Hidrojen bağında hidrojen atomu bir donör (X) ile bir akseptör (Y) arasında ortaklanır; X–H···Y biçiminde gösterilir (Slayt 15). X ve Y, elektronegatifliği yüksek veya serbest elektron çifti taşıyan heteroatomlardır: oksijen, azot, kükürt (Slayt 15). Elektron çifti C=O, –OH, –NH2, imino gibi gruplardan gelir; elektron eksikliği olan hidrojen hidroksil, tiyol ve amino gruplarındadır (Slayt 15). Hidrojen atomu küçük olduğu ve elektron bulutundan yoksun olduğu için bu etkileşim için idealdir (Slayt 16). Aynı molekülün iki grubu arasındaki bağ molekül içi, farklı moleküller arasındaki bağ moleküller arası hidrojen bağıdır (Slayt 17). Slayt 16''daki kararlılık sıralaması bu kopyada **kullanılmadı**: sıra işaretleri metin çıkarmada kayboldu. [NOT IN MATERIALS]',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"X–H···Y hidrojen bağında donör (X) tarafı aşağıdakilerden hangisidir?","options":[{"id":"correct","text":"Elektron eksikliği olan hidrojeni taşıyan hidroksil, tiyol veya amino grubu","isCorrect":true},{"id":"ANY_H_IS_DONOR","text":"Karbona bağlı herhangi bir hidrojen","isCorrect":false,"distractorRationale":"Slayta göre X ve Y elektronegatifliği yüksek heteroatomlardır (O, N, S) (Slayt 15)."},{"id":"ROLES_SWAPPED","text":"Serbest elektron çifti taşıyan karbonil oksijeni","isCorrect":false,"distractorRationale":"Serbest elektron çifti veren taraf akseptördür; donör hidrojeni taşıyan taraftır (Slayt 15)."}],"isMultiSelect":false,"explanation":"Hidrojen bağında donör hidrojeni taşıyan hidroksil, tiyol veya amino grubudur; akseptör serbest elektron çifti taşıyan O, N veya S atomudur.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":15}}}'::jsonb, 'X–H···Y hidrojen bağında donör tarafı hangisidir? Hangi grubun hidrojeni bağ verebilir, düşün.',
  '["Donör, hidrojeni \"veren\" taraf. Hangi grupta hidrojen elektron eksikliğine sahip olur?","Slayta göre hidrojen, hidroksil, tiyol veya amino gibi gruplarda elektron eksikliği taşır. Bu gruplardaki ortak atom türüne bak.","Donör, elektron eksikliği olan hidrojeni taşıyan hidroksil, tiyol veya amino grubudur; akseptör serbest elektron çifti taşıyan O, N, S''dir. (Slayt 15)"]'::jsonb, '{"ANY_H_IS_DONOR":{"diagnosis":"Karbona bağlı herhangi bir hidrojenin donör olacağı sanılıyor. Slayta göre X ve Y elektronegatifliği yüksek heteroatomlardır (O, N, S).","slides":[15]},"ROLES_SWAPPED":{"diagnosis":"Donör ile akseptör rolleri karıştırılıyor. Serbest elektron çifti taşıyan taraf akseptör, elektron eksikliği olan hidrojeni taşıyan taraf donördür.","slides":[15]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
  slide_numbers = EXCLUDED.slide_numbers, concept_title = EXCLUDED.concept_title,
  scientific_summary = EXCLUDED.scientific_summary, recommended_widget = EXCLUDED.recommended_widget,
  initial_widget_state = EXCLUDED.initial_widget_state, student_task = EXCLUDED.student_task,
  scaffolding_ladder = EXCLUDED.scaffolding_ladder, misconception_map = EXCLUDED.misconception_map,
  status = EXCLUDED.status, updated_at = now();

INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:hbag_ozellik_etkisi', 'medchem', 'reseptor-etkilesimleri', 5, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[19]::int[], 'Hidrojen bağı özellikleri ve etkiyi değiştirir', 'Hidrojen bağı molekülün fiziksel ve kimyasal özelliklerini genellikle önemli ölçüde değiştirir: çözünürlük, erime derecesi, pKa, partisyon katsayısı ve bazı spektral özellikler (Slayt 19). Bu değişiklikler farmakolojik özelliklerde de fark yaratır (Slayt 19). Molekül içi hidrojen bağı yapabilen salisilik asit antibakteriyel etki gösterir; yapısal izomerleri m- ve p-hidroksibenzoik asit moleküller arası hidrojen bağlarıyla polimer oluşturur ve bu etkiyi göstermez (Slayt 19). Slayt 18''de çıkarılabilen metin yok (muhtemelen yalnızca görsel); bu konseptte kullanılmadı. [NOT IN MATERIALS]',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"Yalnızca salisilik asit antibakteriyel etkilidir; m- ve p-hidroksibenzoik asit değildir. Slayta göre neden?","options":[{"id":"correct","text":"Salisilik asit molekül içi, m- ve p- izomerler moleküller arası hidrojen bağı yapar","isCorrect":true},{"id":"REVERSED_INTRA_INTER","text":"Salisilik asit moleküller arası, m- ve p- izomerler molekül içi hidrojen bağı yapar","isCorrect":false,"distractorRationale":"Bağ türleri ters: salisilik asit molekül içi bağ yapar (Slayt 19)."},{"id":"HBOND_ONLY_PHYSICAL","text":"Hidrojen bağı yalnızca erime derecesini etkiler; fark başka bir nedenden gelir","isCorrect":false,"distractorRationale":"Hidrojen bağı fiziksel özelliklerle birlikte farmakolojik özellikleri de değiştirir (Slayt 19)."}],"isMultiSelect":false,"explanation":"Molekül içi hidrojen bağı yapan salisilik asit antibakteriyeldir; moleküller arası bağlarla polimer oluşturan m- ve p-hidroksibenzoik asit bu etkiyi göstermez.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":19}}}'::jsonb, 'Salisilik asit antibakteriyel, yapısal izomerleri m- ve p-hidroksibenzoik asit değil. Hidrojen bağının türüne bakarak nedenini seç.',
  '["Üçü de izomer; fark atomlarda değil. Hidrojen bağının nerede kurulduğuna bak.","Biri bağı kendi molekülü içinde, diğer ikisi başka moleküllerle kuruyor. Polimer oluşturan hangisi, kendi içinde bağ kuran hangisi?","Salisilik asit molekül içi, m- ve p- izomerler moleküller arası hidrojen bağı yapar. Bu fark özellikleri ve etkiyi değiştirir. (Slayt 19)"]'::jsonb, '{"REVERSED_INTRA_INTER":{"diagnosis":"Bağ türleri ters yerleştiriliyor. Salisilik asit molekül içi, m- ve p-hidroksibenzoik asit moleküller arası hidrojen bağı yapar.","slides":[19]},"HBOND_ONLY_PHYSICAL":{"diagnosis":"Hidrojen bağının yalnızca fiziksel özellikleri etkilediği sanılıyor. Slayta göre fark farmakolojik özelliklere de yansır.","slides":[19]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
  slide_numbers = EXCLUDED.slide_numbers, concept_title = EXCLUDED.concept_title,
  scientific_summary = EXCLUDED.scientific_summary, recommended_widget = EXCLUDED.recommended_widget,
  initial_widget_state = EXCLUDED.initial_widget_state, student_task = EXCLUDED.student_task,
