INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:iyon_dipol_dipol_dipol', 'medchem', 'reseptor-etkilesimleri', 6, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[20,21]::int[], 'İyon-dipol ve dipol-dipol etkileşimleri', 'Karbonla oksijen veya azot gibi heteroatomlar arasındaki elektronegatiflik farkı elektronların asimetrik dağılmasına, yani dipol oluşmasına yol açar (Slayt 20). Dipol gösteren gruplara karbonil bileşikleri (amit, ester, keton), nitriller ve eterler örnektir (Slayt 20). Bu kutuplar zıt işaretli iyonlarla (iyon-dipol) veya diğer kutuplarla (dipol-dipol) zayıf ve geri dönüşümlü bağlar kurar (Slayt 21). Dielektrik sabiti, dipoller arası mesafe ve grupların yerleşimi önemlidir; mesafe dipol-dipol etkileşmelerinde iyon-dipol etkileşmelerine göre daha önemli ve daha küçüktür (Slayt 21).',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"İyon-dipol ve dipol-dipol etkileşimlerinin ortak özelliği hangisidir?","options":[{"id":"correct","text":"Zayıf ve geri dönüşümlü bağlardır","isCorrect":true},{"id":"DIPOLE_EQUALS_IONIC","text":"İyonik bağ kadar güçlüdür","isCorrect":false,"distractorRationale":"Slayta göre bu etkileşimler zayıftır (Slayt 21)."},{"id":"DIPOLE_IS_COVALENT","text":"Kovalan bağ gibi geri dönüşümsüzdür","isCorrect":false,"distractorRationale":"Geri dönüşümsüzlük kovalan bağlara özgüdür; dipol etkileşimleri geri dönüşümlüdür (Slayt 21, 9)."}],"isMultiSelect":false,"explanation":"Karbonil bileşikleri, nitriller ve eterler gibi gruplardaki kutuplar zıt yüklü bölgelerle zayıf ve geri dönüşümlü bağlar kurar.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":21}}}'::jsonb, 'İyon-dipol ve dipol-dipol etkileşimlerinin ortak özelliği nedir? Bağ gücü ve kalıcılığı üzerinden düşün.',
  '["Dipol, iki atom arasındaki elektronegatiflik farkından doğar; kısmi yük taşır, tam iyon değildir. Bu, bağın gücü hakkında ne düşündürüyor?","Slaytta bu iki etkileşim için iki sıfat geçiyor: biri güç, biri kalıcılık hakkında. İyonik ve kovalan bağlarla kıyasla.","İyon-dipol ve dipol-dipol etkileşimleri zayıf ve geri dönüşümlü bağlardır. (Slayt 21)"]'::jsonb, '{"DIPOLE_EQUALS_IONIC":{"diagnosis":"Dipol etkileşiminin iyonik bağ kadar güçlü olduğu sanılıyor. Slayta göre zayıf ve geri dönüşümlüdür.","slides":[21]},"DIPOLE_IS_COVALENT":{"diagnosis":"Dipol etkileşimi kovalan bağ gibi kalıcı sanılıyor. Geri dönüşümsüz etki kovalan bağlara özgüdür; dipol etkileşimleri geri dönüşümlüdür.","slides":[21,9]}}'::jsonb, 'draft', now())
