INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:yuk_transferi', 'medchem', 'reseptor-etkilesimleri', 7, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[22,23]::int[], 'Yük transfer etkileşimleri', 'Yük transferi, bir tür moleküler dipol-dipol etkileşmesidir: elektron donörü molekülden akseptör moleküle yük geçer ve yük transfer kompleksi oluşur (Slayt 22). Gücü, donörün iyonizasyon potansiyeli ile akseptörün elektron afinitesi arasındaki farkla orantılıdır (Slayt 22). Zayıf bir etkileşimdir; ancak diğer bağ tipleriyle birlikte toplam ilaç etkisinde rol oynar (Slayt 22). Elektron veren sübstitüentli alken, alkin ve aromatik gruplar ile ortaklanmamış elektron çifti taşıyan gruplar donör; elektron çeken sübstitüentli alken, alkin ve aromatik yapılar ile zayıf asidik protonlar akseptördür (Slayt 22). Klasik örnek, aromatik halkaların pi sistemlerinin üst üste gelmesidir (Slayt 22). Klorotalonil örneğinin yapısı bu kopyada kullanılmadı. [NOT IN MATERIALS]',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"Yük transfer etkileşiminde elektron donörü rolünü hangi yapı üstlenir?","options":[{"id":"correct","text":"Elektron veren sübstitüentli aromatik halka","isCorrect":true},{"id":"EWG_IS_DONOR","text":"Elektron çeken sübstitüentli aromatik halka","isCorrect":false,"distractorRationale":"Elektron çeken sübstitüentli yapılar akseptördür (Slayt 22)."},{"id":"WEAK_ACID_PROTON_IS_DONOR","text":"Zayıf asidik proton","isCorrect":false,"distractorRationale":"Zayıf asidik protonlar elektron akseptörüdür (Slayt 22)."}],"isMultiSelect":false,"explanation":"Donör, elektron veren sübstitüentli alken, alkin ve aromatik gruplar veya ortaklanmamış elektron çifti taşıyan gruplardır. Akseptör, elektron çeken yapılar ve zayıf asidik protonlardır.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":22}}}'::jsonb, 'Yük transfer kompleksinde elektron veren taraf hangisidir? Sübstitüentin elektron verip vermediğine göre karar ver.',
  '["Donör elektron verir, akseptör elektron alır. Hangi sübstitüent elektron çekmez, tam tersine elektron kazandırır?","Metoksi gibi elektron veren sübstitüentli halka donör rolüne, nitro gibi elektron çeken sübstitüentli halka akseptör rolüne uyar. Hangi seçenek donörü anlatıyor?","Elektron veren sübstitüentli aromatik, alken veya alkin gruplar ile ortaklanmamış elektron çifti taşıyan gruplar donördür. (Slayt 22)"]'::jsonb, '{"EWG_IS_DONOR":{"diagnosis":"Elektron çeken sübstitüentli yapı donör sanılıyor. Slayta göre bu yapılar akseptördür.","slides":[22]},"WEAK_ACID_PROTON_IS_DONOR":{"diagnosis":"Zayıf asidik proton donör sanılıyor. Slayta göre zayıf asidik protonlar elektron akseptörüdür.","slides":[22]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
