INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:vdw_hidrofobik', 'medchem', 'reseptor-etkilesimleri', 8, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[24,25]::int[], 'Van der Waals ve hidrofobik etkileşimler', 'Van der Waals güçleri, moleküllerin polarizlenebilme özelliğinden doğar ve yüksüz atomlar birbirine çok yaklaşınca ortaya çıkar (Slayt 24). Apolar kısımlardaki elektron yoğunluğunun asimetrik dağılımı geçici dipoller oluşturur; apolar gruplar yaklaşık 4–6 Å yaklaşınca bir molekülün geçici dipolü diğerinde zıt dipol indükler (Slayt 24). Zayıf güçlerdir, ama diğer etkileşimlerle birlikte ilaç-reseptör kompleksi için önemlidir (Slayt 24). Hidrofobik etkileşimde apolar bölgeler yaklaşırken çevrelerindeki su molekülleri sıkıştırılıp dışarı itilir (Slayt 25). Etkileşimin enerjisi oluşan bağla doğrudan ilgili değildir; esas olarak sistemin entropisindeki artışla ilgilidir (Slayt 25).',
  'PredictThenReveal', '{"type":"PredictThenReveal","config":{"prompt":"Hidrofobik etkileşimin enerjisi esas olarak nereden gelir?","scenarioDescription":"Bir ilacın lipofilik sübstitüenti, reseptörün apolar bölgesine yaklaşıyor. Aradaki su molekülleri sıkıştırılıp dışarı itiliyor.","options":[{"id":"correct","label":"Sistemin entropisindeki artıştan","isCorrect":true},{"id":"HYDROPHOBIC_IS_A_BOND","label":"İki grup arasında oluşan güçlü bir bağdan","isCorrect":false,"misconceptionFeedback":"Enerji, oluşan bağla doğrudan ilgili değildir; entropi artışıyla ilgilidir (Slayt 25)."},{"id":"CONFUSES_WITH_VDW","label":"Apolar gruplar arasındaki geçici dipol çekiminden","isCorrect":false,"misconceptionFeedback":"Geçici dipol çekimi Van der Waals güçleridir (Slayt 24); hidrofobik etkileşimin enerjisi entropi artışından gelir (Slayt 25)."}],"revealedOutcome":"Hidrofobik etkileşimin enerjisi bağ oluşumundan değil, esas olarak sistemin entropisindeki artıştan gelir.","explanation":"Apolar bölgeler yaklaşırken çevrelerindeki su molekülleri dışarı itilir; bu, sistemin entropisini artırır.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":25}}}'::jsonb, 'İki apolar bölge yaklaşırken aralarındaki sular dışarı itiliyor. Önce tahmin et: bu etkileşimin enerjisi nereden geliyor?',
  '["Burada iki grup arasında klasik bir bağ kurulmuyor. Suyun ne yaptığına bak.","Sıkışmış sular serbest kalınca sistemin düzensizliği değişiyor. Bu hangi termodinamik büyüklükle ilgili?","Hidrofobik etkileşimin enerjisi bağ oluşumuyla doğrudan ilgili değildir; esas olarak sistemin entropisindeki artışla ilgilidir. (Slayt 25)"]'::jsonb, '{"HYDROPHOBIC_IS_A_BOND":{"diagnosis":"Hidrofobik etkileşim bir bağ gibi düşünülüyor. Slayta göre enerji, oluşan bağla doğrudan ilgili değildir.","slides":[25]},"CONFUSES_WITH_VDW":{"diagnosis":"Hidrofobik etkileşim ile Van der Waals çekimi karıştırılıyor. Van der Waals geçici dipollerden doğar; hidrofobik etkileşimin enerjisi entropi artışından gelir.","slides":[24,25]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
  slide_numbers = EXCLUDED.slide_numbers, concept_title = EXCLUDED.concept_title,
  scientific_summary = EXCLUDED.scientific_summary, recommended_widget = EXCLUDED.recommended_widget,
  initial_widget_state = EXCLUDED.initial_widget_state, student_task = EXCLUDED.student_task,
