INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:selasyon', 'medchem', 'reseptor-etkilesimleri', 9, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[26,28,30]::int[], 'Şelasyon ve dişlilik', 'Şelat oluşumu, ilacın in vivo aktivitesinde önemli bağ oluşumlarından biridir (Slayt 26). Geçiş metal katyonları ile elektron donörü gruplar arasında koordine kovalan bağlarla oluşan bileşiğe kompleks denir; kompleks siklik yapıdaysa şelat adını alır (Slayt 26). Koordine kovalan bağda bağı oluşturan iki elektron aynı atomdan gelir; elektron eksikliği ve boş orbitali olan metal katyonu akseptördür (Slayt 26). Metale elektron çifti veren maddeye ligand denir; iki veya daha fazla elektron donörü grup taşıyan ligand şelat oluşturur (Slayt 28). İki, üç veya daha fazla donör grup taşıyan ligandlar sırasıyla bidentat, tridentat, polidentat adını alır (Slayt 30). Slayt 30''a göre etilen diamin, glisin ve 8-hidroksikinolin anyonu bidentat, dietilentriamin tridentat ligandlara örnektir (Slayt 30). Slayt 27''deki koordinasyon sayıları tablosunun yük işaretleri doğrulanmadığı için kullanılmadı. [NOT IN MATERIALS]',
  'MultipleChoice', '{"type":"MultipleChoice","config":{"prompt":"Etilen diamin ve dietilentriamin ligandları dişlilik açısından nasıl sınıflanır?","options":[{"id":"correct","text":"Etilen diamin bidentat, dietilentriamin tridentat","isCorrect":true},{"id":"DENTICITY_REVERSED","text":"Etilen diamin tridentat, dietilentriamin bidentat","isCorrect":false,"distractorRationale":"Dişlilik, donör grup sayısına göre belirlenir; etilen diamin iki, dietilentriamin üç donör taşır (Slayt 30)."},{"id":"SAME_DENTICITY","text":"İkisi de bidentat, çünkü ikisi de amin grubu taşır","isCorrect":false,"distractorRationale":"Dişlilik grup türüne değil, donör grup sayısına bağlıdır (Slayt 30)."}],"isMultiSelect":false,"explanation":"İki donör grup taşıyan ligand bidentat, üç donör grup taşıyan tridentattır. Slayt 30 etilen diamini bidentat, dietilentriamini tridentat örnek olarak verir.","source":{"file":"İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf","page":30}}}'::jsonb, 'Etilen diamin ile dietilentriamin ligandları dişlilik açısından nasıl sınıflanır? Donör grup sayısına göre karar ver.',
  '["Dişlilik, ligandın taşıdığı elektron donörü grup sayısına bağlı. Her iki ligandda kaç azot donörü var, say.","İki donör grup bidentat, üç donör grup tridentat demek. Etilen diamin iki, dietilentriamin üç azot taşır; hangi seçenek buna uyuyor?","Etilen diamin bidentat, dietilentriamin tridentattır; dişlilik donör grup sayısına göre belirlenir. (Slayt 30)"]'::jsonb, '{"DENTICITY_REVERSED":{"diagnosis":"Dişlilik sıralaması ters kuruluyor. Slayta göre etilen diamin bidentat, dietilentriamin tridentattır.","slides":[30]},"SAME_DENTICITY":{"diagnosis":"Aynı tür grup taşıyan ligandlar aynı dişlilikte sanılıyor. Dişlilik grup türüne değil, donör grup sayısına göre belirlenir.","slides":[30]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
