INSERT INTO public.lecture_concepts
  (id, course_id, lecture_slug, sort_order, source_deck, slide_numbers, concept_title, scientific_summary,
   recommended_widget, initial_widget_state, student_task, scaffolding_ladder, misconception_map, status, updated_at)
VALUES ('rr:dibukain_entegrasyon', 'medchem', 'reseptor-etkilesimleri', 10, 'İlaç Reseptör Etkileşimi-Kimyasal Bağlar.pdf',
  ARRAY[33]::int[], 'Entegrasyon görevi: Dibukain', 'Slayt 33, dibukain molekülünün olası bir reseptörle kurabileceği etkileşimleri gösterir: hidrofobik, hidrojen bağı, dipol-dipol, iyon-dipol, yük transferi, iyon veya iyon-dipol (Slayt 33). Hangi molekül bölgesinin hangi etkileşimi kurduğu yalnızca çizimde verilmiştir ve metinden güvenilir biçimde okunamadı. [NOT IN MATERIALS] Dibukain SMILES''i slayttan çıkarılamadı; RDKit ile doğrulanana kadar `verified: false`. [NOT IN MATERIALS]',
  'ReceptorLigandMatcher', NULL, 'Dibukainin her bölgesini seç ve bu bölgenin reseptörle kurabileceği etkileşim türünü belirle.',
  '["Önce molekülün apolar bölgelerini bul. Bu bölgeler hangi etkileşimi kurar?","Amit grubuna bak: hem hidrojen verebilir hem alabilir. Bu özellik hangi etkileşimlere izin verir?","Bölge-etkileşim eşlemesi, slayt 33''ün çizimi hoca ve siz tarafınızdan doğrulandıktan sonra gösterilecek."]'::jsonb, '{"ONE_GROUP_ONE_BOND":{"diagnosis":"Bir fonksiyonel grubun yalnızca tek tür etkileşim kurduğu sanılıyor. Slayt 33, aynı molekülün birden fazla etkileşim türü kurabildiğini gösterir.","slides":[33]},"FORGET_HYDROPHOBIC":{"diagnosis":"Apolar bölgeler atlanıyor. Slayt 33''te hidrofobik etkileşim açıkça listelenir.","slides":[25,33]}}'::jsonb, 'draft', now())
ON CONFLICT (id) DO UPDATE SET
  lecture_slug = EXCLUDED.lecture_slug, sort_order = EXCLUDED.sort_order, source_deck = EXCLUDED.source_deck,
